class Key
  public readonly property N: int;
  public constructor(n: int) N := n; end constructor;
  public method Equals(other: Key): bool => N = other.N;        // the Object slot (§8.3)
  public override method GetHashCode(): int => N;
  public method Equals(other: IBase): bool => N = other.Id();   // another type: fills no slot
end Key;                   // hashable: `k.Equals(k2)` is exact at the slot, no ambiguity (§3.6 (d))
