    using var k := new Key(7);
    var r := Second<Key, Tag>(k, t);  // `k.Equals(x)` at x: IFoo is §22.6's ambiguity: the slot and
  end Run;                            //   Equals(IBase) both convert; §9.2 rejects the second kind only
