static class Demo
  public static method Twice(n: int): int => n * 2;
  public static method Agree<T>(a: T, b: T): bool where T: hashable, notnull =>
    not (a = b) or a.GetHashCode() = b.GetHashCode();   // §8.3's invariant, which hashable promises
  public static method Run()
    var fn1: (int) -> int := Demo.Twice;
    var fn2: (int) -> int := Demo.Twice;  // a second evaluation: equal to fn1 by §27.7.1
    var f: Object := fn1;                 // capture-free: admitted at Object (§28.3 set-erasing)
    var g: Object := fn2;
    var ok := Agree<Object>(f, g);        // Object is hashable (§3.6); f = g dispatches §27.7.1's
  end Run;                                //   equality; the hashes are per-function-object identity
end Demo;                                 //   (clause (e)): ok turns on allocation, "unobservable" (§27.7.1)

static class Demo
  public static method Twice(n: int): int => n * 2;
  public static method Run()
    var fn1: (int) -> int := Demo.Twice;
    var fn2: (int) -> int := Demo.Twice;   // equal to fn1 by §27.7.1 ("every other reference to M")
    using var s := new Set<Object>();      // Object is hashable (§3.6): the set forms
    s.Add(fn1);                            // capture-free: admitted at the set-erasing T slot (§28.3)
    s.Add(fn2);                            // Equals true, GetHashCode Object's identity per function
    Console.WriteLine(s.Count);            //   object (clause (e)): 1 or 2, by allocation and bucket
  end Run;
end Demo;

class Keep<T>
  private _v: T?;
  public method Put(x: IReadOnlySpan<int>)
    if x is T then   // §12.7: x is a narrowing carrier, flow-narrowed to T
      _v := x;       // no `as`, no typed pattern: §9.7's new sentence names neither
    end;
  end Put;
end Keep;

static class Demo
  public static method Run(k: Keep<Object>)
    do
      var a: Array<int> := [1, 2, 3];
      k.Put(a.AsSpan());   // admitted: parameter declared IReadOnlySpan<int>
    end;                   // a out of scope; reading 2: k._v is an Object boxing a span over it
  end Run;
end Demo;
// Reading 1 (narrowed read still "by its declared type"): `_v := x` rejected at the declaration.
// Reading 2 (narrowed static type T): admitted at Keep<Object>; nothing reads the store per instantiation.

