// module M1
public interface I
  method M<T>(j: J, n: int, x: T);
end I;
public interface J
  method N<T>(i: I, n: int, x: T);
end J;
public record Box<T>(V: T);
class C2: I   // module M2 (imports M1); internal: §2.8.2 carries none of its bodies
  public method M<T>(j: J, n: int, x: T)
    H<Box<T>>(j, this, n, new Box<T>(x));   // edge I.M -> H at Box<T>: an implementation's request, carried
  end M;
  private static method H<U>(j: J, i: I, n: int, x: U)
    if n > 0 then j.N<U>(i, n - 1, x); end;  // edge H -> J.N at U: no implementation's request
  end H;
end C2;
public static class F2
  public static method Make(): owned I => new C2();
end F2;
public class C3: J   // module M3 (imports M1)
  public method N<T>(i: I, n: int, x: T)
    i.M<T>(this, n, x);                      // edge J.N -> I.M at T, carried
  end N;
end C3;
// App: F2.Make().M<int>(new C3(), 5, 0) -- A: H -> J.N is in the union, rejected; B: it is not, admitted unbounded

