class Host
  public async method Work(): Task
    await Task.Delay(10);
  end Work;
  public async method Run(): Task
    using var t0 := Work();
    var box := new Box<Task>(t0);
    var f := box.Hand() as (Box<Task>) -> Task;   // narrowed from `Object`
    using var t := f!(box);   // the invocation keys a `Task` return as a mint: adopts t0, which Run owns
    await t;
  end Run;                    // t and t0 are one task, disposed twice
