interface ISink<V>
  method Put(f: () -> V);              // depth one; ISink<Task> is excluded, ISink<IEnumerable<int>> is not
end ISink;
class Holder<T>(v: T)
  private _v: T := v;
  public method Lend(s: ISink<T>)
    s.Put(lambda() => _v);             // a receiver-sourced lend at the pre-substitution bare-T slot
  end Lend;
end Holder;
class Drainer: ISink<IEnumerable<int>>
  public method Put(f: () -> IEnumerable<int>)
    for var x in f() do                // keyed on the implementer's declared slot: an owned frame
      Console.WriteLine($"{x}");
    end;                               // the loop's using var __source disposes Holder's _v
  end Put;
end Drainer;
static class Use
  public static method Run()
    using var xs: Array<int> := [1, 2, 3];
    var h := new Holder<IEnumerable<int>>(xs);
    using var d := new Drainer();
    h.Lend(d);
    xs.Add(4);                         // Run's own array, already disposed
  end Run;
end Use;

class Item public N: int; end Item;
interface ISink<V>
  method Take(f: (V) -> ());           // depth one over V
end ISink;
class Keep<T>
  private _last: T?;
  public method Arm(s: ISink<T>)
    s.Take(lambda(x) => do _last := x; end);  // formed at (T) -> (), passed to a function-typed parameter
  end Arm;
  public method Last(): T? => _last;  // a bare-T return: a receiver-sourced borrow
end Keep;
class Feeder: ISink<() -> int>
  public method Take(f: (() -> int) -> ())
    using var it := new Item();
    f(lambda() => it.N);               // a capture-bearing closure into a concrete function-typed slot
  end Take;                            // `it` disposed; Keep's _last still holds the closure
end Feeder;
static class Use
  public static method Run()
    var k := new Keep<() -> int>();
    k.Arm(new Feeder());               // an unbound owned temporary, disposed after the call
    _ := k.Last()!();                  // invokes a closure over the disposed `it`
  end Run;
end Use;

