class Hub<T>
  public scoped Handler: ((T) -> ())?;                        // FieldDecl admits any visibility
  public method Register(scoped h: (T) -> ()) => Handler := h;  // §28.14 bound 5: a scoped parameter
  public method Arm() => Register(lambda(t: T) => Registry.Sink.Keep(t));  // "passed to a function-typed parameter"
end Hub;
static class Demo
  public static method Run(h: Hub<() -> int>)
    h.Arm();
    using var it := new Item();
    var g: () -> int := lambda() => it.N();   // source set {it}
    h.Handler?(g);   // plain slot of an invoked function value: call-bounded, g admitted
  end Run;           // it disposed; Registry.Sink._o holds g
end Demo;
